import { streamSimpleAnthropic } from "./vendor/anthropicStock";
import { getAnthropicCcSyntheticUserId } from "./userId";

export function streamAnthropicCc(
	model: Model<Api>,
	context: TranscriptContext,
	options?: SimpleStreamOptions,
): AssistantMessageEventStream {
	context = asTranscriptContext(context);
	const initialSystem = getInitialSystemMessage(context.messages);
	const nativeSystem = (model as Model<"anthropic-messages">).compat?.supportsMidConvoSystemMessages === true;
	const userSystemPrompt = nativeSystem && initialSystem
		? getSystemMessageText(initialSystem)
		: getCurrentSystemPrompt(context.messages);
	const apiKey = resolveAnthropicCcApiKey(options);
	if (!apiKey) throw new Error("No anthropic-cc API key. Run /login anthropic-cc.");

	const baseline = getAnthropicCcBaseline();
	const sessionId = resolveAnthropicCcSessionId(options?.sessionId);
	const requestHeaders = buildAnthropicCcHeaders({
		apiKey,
		sessionId,
		baseline,
		baseHeaders: options?.headers,
		transportBetaFlags: resolveAnthropicCcTransportBetaFlags(model as any, context),
	});
	const callerOnPayload = options?.onPayload as undefined | ((payload: unknown, model?: unknown) => unknown | Promise<unknown>);
	const isOAuth = isAnthropicCcOAuthToken(apiKey);
	const fallbackSyntheticUserId = getAnthropicCcSyntheticUserId();
	const wrappedModel = {
		...model,
		baseUrl: model.baseUrl ?? "https://api.anthropic.com",
		headers: requestHeaders,
	} as any;

	return streamSimpleAnthropic(wrappedModel, context, {
		...options,
		apiKey,
		headers: requestHeaders,
		onPayload: async (payload: unknown, modelArg?: unknown) => {
			const stockPayload = payload as Record<string, any>;
			let next: Record<string, any> = applyAnthropicCcBodyOverrides(stockPayload, {
				baseline,
				syntheticUserId: fallbackSyntheticUserId,
				userSystemPrompt,
				cacheControl: resolveAnthropicCcCacheControl(stockPayload),
				sanitizeUserSystemPrompt: isOAuth,
			}) as Record<string, any>;
			const providerUserId =
				typeof next.metadata?.user_id === "string"
					? next.metadata.user_id
					: fallbackSyntheticUserId;
			// From this point this local holds the provider-established identity, which
			// may be explicit metadata rather than the file-backed fallback.
			const syntheticUserId = providerUserId;

			const callerResult = await callerOnPayload?.(next, modelArg);
			if (callerResult !== undefined) next = callerResult as Record<string, any>;
			const sanitized = sanitizeAnthropicCcRequestParams(
				model as any,
				applyAnthropicCcToolPolicy(next),
			);
			return {
				...sanitized,
				metadata: {
					...(sanitized.metadata ?? {}),
					user_id: syntheticUserId,
				},
			};
		},
	} as any);
}

import { expect, it } from "bun:test";
import { buildAnthropicCcHeaders } from "../src/anthropic-cc/overrides";

function has(headers: Record<string, string | null>, name: string) {
	return Object.keys(headers).some((key) => key.toLowerCase() === name.toLowerCase());
}

it("removes the opposite authentication mode after merging caller headers", () => {
	const common = { sessionId: "11111111-1111-4111-8111-111111111111" };
	const oauth = buildAnthropicCcHeaders({
		...common,
		apiKey: "sk-ant-oat-token",
		baseHeaders: { "X-Api-Key": "must-not-leak" },
	});
	if (has(oauth, "x-api-key")) {
		throw new Error("OAuth headers retained a caller x-api-key");
	}
	expect(oauth.authorization).toBe("Bearer sk-ant-oat-token");

	const apiKey = buildAnthropicCcHeaders({
		...common,
		apiKey: "sk-ant-api-key",
		baseHeaders: { Authorization: "Bearer must-not-leak" },
	});
	expect(has(apiKey, "authorization")).toBe(false);
	expect(apiKey["x-api-key"]).toBe("sk-ant-api-key");
});

import { expect, it } from "bun:test";
import {
	buildAnthropicCcHeaders,
	resolveAnthropicCcTransportBetaFlags,
} from "../src/anthropic-cc/overrides";

const baseline = {
	version: "2.1.261",
	model: "claude-fable-5-1",
	endpointPath: "/v1/messages?beta=true",
	userAgent: "claude-cli/2.1.261 (external, sdk-cli)",
	betaFlags: ["claude-code-20250219", "per-turn-control-2026-07-01", ""],
	systemPrelude: ["billing", "identity"],
};

it("merges captured caller and managed transport betas without allowlisting or case duplicates", () => {
	const headers = buildAnthropicCcHeaders({
		apiKey: "sk-ant-api-key",
		sessionId: "session",
		baseline,
		transportBetaFlags: resolveAnthropicCcTransportBetaFlags({
			compat: { supportsMidConvoEffort: true },
		}),
		baseHeaders: {
			"Anthropic-Beta": "caller-future-2099-01-01, CLAUDE-CODE-20250219, ,caller-future-2099-01-01",
		},
	});
	expect(headers["Anthropic-Beta"]).toBeUndefined();
	expect(headers["anthropic-beta"].split(",")).toEqual([
		"claude-code-20250219",
		"per-turn-control-2026-07-01",
		"caller-future-2099-01-01",
		"mid-conversation-output-config-2026-07-01",
		"thinking-binding-controls-2026-08-01",
	]);
	expect(headers["x-api-key"]).toBe("sk-ant-api-key");
	expect(headers.authorization).toBeUndefined();
});

import { expect, it } from "bun:test";
import { buildAnthropicCcHeaders } from "../src/anthropic-cc/overrides";

it("retains case-insensitive null header tombstones without weakening owned authentication", () => {
  const headers = buildAnthropicCcHeaders({
    apiKey: "fixture-key", sessionId: "fixture-session",
    baseHeaders: { "USER-AGENT": null, "X-App": null, "X-Fixture": "yes", authorization: null },
  });
  if (headers["user-agent"] !== null) throw new Error("Claude headers discarded a suppression tombstone");
  expect(headers["x-app"]).toBeNull();
  expect(headers["x-fixture"]).toBe("yes");
  expect(headers).not.toHaveProperty("USER-AGENT");
  expect(headers["x-api-key"]).toBe("fixture-key");
  expect(headers).not.toHaveProperty("authorization");
  expect(headers["anthropic-beta"]).toBeString();
});

import { expect, it } from "bun:test";
import { normalizeContext } from "@earendil-works/pi-ai";
import {
	INLINE_TOOLS_BETA,
	buildAnthropicCcHeaders,
	resolveAnthropicCcTransportBetaFlags,
} from "../src/anthropic-cc/overrides";

const tool = (name: string) => ({ name, description: name, parameters: { type: "object", properties: {}, required: [] } }) as any;
const withTools = normalizeContext({ systemPrompt: "base", tools: [tool("read")], messages: [{ role: "user", content: "PING", timestamp: 1 }] } as any);
const withoutTools = normalizeContext({ systemPrompt: "base", messages: [{ role: "user", content: "PING", timestamp: 1 }] } as any);
const native = { compat: { supportsMidConvoSystemMessages: true, supportsMidConvoToolChanges: true } };
const managedNative = { compat: { ...native.compat, supportsMidConvoEffort: true } };

const baseline = {
	version: "2.1.261",
	model: "claude-fable-5-1",
	endpointPath: "/v1/messages?beta=true",
	userAgent: "claude-cli/2.1.261 (external, sdk-cli)",
	betaFlags: ["claude-code-20250219"],
	systemPrelude: ["billing", "identity"],
};

it("adds the inline-tools beta for native inline requests", () => {
	expect(INLINE_TOOLS_BETA).toBe("inline-tools-2026-09-15");
	expect(resolveAnthropicCcTransportBetaFlags(native, withTools)).toEqual(["inline-tools-2026-09-15"]);
	expect(resolveAnthropicCcTransportBetaFlags(managedNative, withTools)).toEqual([
		"mid-conversation-output-config-2026-07-01",
		"thinking-binding-controls-2026-08-01",
		"inline-tools-2026-09-15",
	]);
});

it("omits the inline-tools beta when native inline mode is inactive", () => {
	expect(resolveAnthropicCcTransportBetaFlags(native, withoutTools)).toEqual([]);
	expect(resolveAnthropicCcTransportBetaFlags({ compat: { supportsMidConvoToolChanges: true } }, withTools)).toEqual([]);
	expect(resolveAnthropicCcTransportBetaFlags(native)).toEqual([]);
});

it("never derives the legacy mid-conversation tool-changes beta", () => {
	for (const flags of [
		resolveAnthropicCcTransportBetaFlags(native, withTools),
		resolveAnthropicCcTransportBetaFlags(managedNative, withTools),
		resolveAnthropicCcTransportBetaFlags({ compat: { supportsMidConvoToolChanges: true } }),
	]) {
		expect(flags).not.toContain("mid-conversation-tool-changes-2026-07-01");
	}
});

it("composes the inline beta with baseline and caller flags without duplicates", () => {
	const headers = buildAnthropicCcHeaders({
		apiKey: "sk-ant-api-key",
		sessionId: "session",
		baseline: baseline as any,
		transportBetaFlags: resolveAnthropicCcTransportBetaFlags(native, withTools),
		baseHeaders: { "anthropic-beta": "inline-tools-2026-09-15,mid-conversation-tool-changes-2026-07-01" },
	});
	expect(headers["anthropic-beta"].split(",")).toEqual([
		"claude-code-20250219",
		"inline-tools-2026-09-15",
		"mid-conversation-tool-changes-2026-07-01",
	]);
});

import { expect, it } from "bun:test";
import { buildAnthropicCcHeaders } from "../src/anthropic-cc/overrides";

it("adds OAuth exactly once without removing captured caller or transport betas", () => {
	const common = {
		sessionId: "session",
		baseline: {
			version: "2.1.261",
			model: "claude-fable-5-1",
			endpointPath: "/v1/messages?beta=true",
			userAgent: "claude-cli/2.1.261 (external, sdk-cli)",
			betaFlags: ["claude-code-20250219"],
			systemPrelude: ["billing", "identity"],
		},
		transportBetaFlags: ["thinking-binding-controls-2026-08-01"],
		baseHeaders: { "ANTHROPIC-BETA": "caller-future-2099-01-01" },
	};
	const api = buildAnthropicCcHeaders({ ...common, apiKey: "sk-ant-api-key" });
	const oauth = buildAnthropicCcHeaders({ ...common, apiKey: "sk-ant-oat-token" });
	const duplicate = buildAnthropicCcHeaders({
		...common,
		apiKey: "sk-ant-oat-token",
		baseHeaders: {
			"ANTHROPIC-BETA": "caller-future-2099-01-01,OAUTH-2025-04-20",
		},
	});
	const apiBetas = api["anthropic-beta"].split(",");
	const oauthBetas = oauth["anthropic-beta"].split(",");
	const duplicateBetas = duplicate["anthropic-beta"].split(",");

	expect(oauthBetas).toEqual([...apiBetas, "oauth-2025-04-20"]);
	expect(duplicateBetas.map((beta) => beta.toLowerCase())).toEqual(
		oauthBetas.map((beta) => beta.toLowerCase()),
	);
	expect(duplicateBetas.filter((beta) => beta.toLowerCase() === "oauth-2025-04-20")).toHaveLength(1);
	expect(oauth.authorization).toBe("Bearer sk-ant-oat-token");
	expect(oauth["x-api-key"]).toBeUndefined();
});
